		'short' => 'Kesik başlı 34° Kağıda Dizili Çivi; 2,87–3,3 mm çap, 50–100 mm boy, düz / ring / helikal gövde. Dar şarjörlü karkas tabancaları için.',
		'body' => '34° Kağıda Dizili Çivi, kesik (D) başlı çivilerin kağıt bantla sık dizilmesiyle elde edilir; bu sayede şarjöre daha çok çivi sığar ve dar köşelerde çalışma kolaylaşır. Sertel aralığı 2,87–3,3 mm çap ve 50–100 mm boydur. Gövde düz, ring veya helikal; kaplama parlak, galvaniz ya da difüzyon olarak üretilir.

Tipik işler: ahşap karkas ev, çatı makası, kalıp iskelesi, ağır sandık ve kablo makarası montajı. Kağıt bant yağmurda yumuşayabileceği için ürün kapalı ortamda saklanır ve 34° kağıt şerit şarjörlü tabancalarla kullanılır; 30°–34° arası tabancaların çoğu bu şeridi kabul eder, modelinizi söylemeniz yeterli.

KOÇİST\'te kağıda dizili çivi için ekonomik fiyat ve aynı gün teklif alırsınız; miktar arttıkça birim fiyat düşer. İstanbul ve Trakya\'ya kendi araçlarımızla, Anadolu\'ya anlaşmalı kargo ile gönderiyoruz. Çatalca showroomumuzda numune hazır. 0212 648 19 19.',
