		'body' => 'Çelik Beton Çivisi, sertleştirilmiş çelikten üretilir ve betona, tuğlaya ya da sıvaya çekiçle çakılır. Sertel paket listesinde altı ölçü vardır: 3x30 mm (100\'lük poşet, kolide 100 poşet), 4x40, 4x50 ve 4x60 mm (100\'lük poşet, kolide 50 poşet), 5x80 ve 5x100 mm (100\'lük poşet, kolide 25 poşet). Böylece koli başına 2.500 ile 10.000 adet arasında çivi gelir.

Palet ve ambalaj atölyelerinde beton zemine ahşap kızak, raf ayağı ve koruyucu çıta sabitlemede; şantiyede kalıp çıtası, süpürgelik ve duvar askısı işlerinde kullanılır. Kafa düz ve geniştir; çakarken koruyucu gözlük önerilir.

