		'body' => 'AKD TCN45R Çatı Çivi Tabancası (Shingle), bu kategoride palet dışına çıkan tek modeldir: shingle, bitümlü örtü ve çatı kaplama çivileri için üretilmiştir. Sertel tablosunda çivi çapı 3,05 mm, kafa çapı 10,5 mm, boy 19–45 mm, hazne 120 adet ve ağırlık 2,43 kg olarak geçer. Geniş kafa, örtüyü yırtmadan sabitler; hafif gövde çatıda uzun süre çalışmayı kolaylaştırır.

