		'body' => 'Dar taçlı ve kalın kesitli bir tel arıyorsanız 90 Serisi 18 GA Zımba Teli (Testere Uç) bu ihtiyaca göre tasarlanmıştır. Tel kesiti 1,25x1,00 mm\'dir; 9010, 9020, 9025, 9030, 9035 ve 9040 kodlarıyla 10–40 mm arası altı boy sunulur. Dizide 100, kutuda 5.000 tel vardır. Koli 30 mm\'ye kadar 10 kutu, 35–40 mm\'de 8 kutudur.

