		'short' => 'Depo ve ofis evrakı için Ofis Zımba Teli: 10/1 ve 24/06 tipleri, dizide 50 tel, kutuda 1.000 adet.',
		'body' => 'Palet, kasa ya da tel siparişi veren her işletmenin bir de ofis tarafı vardır: irsaliye, fatura nüshası, teslim tutanağı ve ölçü föyleri. Ofis Zımba Teli bu evrak trafiğinin sarf malzemesidir. Sertel listesinde iki tip bulunur: 10/1 (4,75 mm) ve 24/06 (5,79 mm). Her kutu 20 diziden oluşur, dizide 50 tel vardır; kutu başına toplam 1.000 adet eder. Koli 10/1\'de 1.000 kutu, 24/06\'da 400 kutudur.

