		'body' => 'Klipsler, halka biçiminde kapanarak iki teli ya da teli bir kumaşa bağlayan bağlantı elemanlarıdır; sektörde C-ring ya da domuz halkası adıyla da bilinir. Sertel tablosunda beş tip görülür: CL13, CL17, CL18, CL23 ve CL24. CL13, CL17 ve CL18 hem rulo hem şerit paketle, CL23 ile CL24 yalnızca şerit paketle gelir.

