		'body' => 'Paslanmaz Klipsler, standart klipslerin dış ortama ve neme dayanıklı versiyonudur. Sertel görselinde iki tip yer alır: AKD M55 tabancasıyla kullanılan CL35 ve AKD M46 ile kullanılan CL18. CL35 şerit paketle, kolide 4.000 adet olarak gelir. CL18 rulo ya da şerit seçenekli, kolide 10.000 adettir. 

