		'short' => 'Şantiyede demir bağlamanın vazgeçilmezi Tavlı Tel: 0,9–4,0 mm çap, düşük karbonlu, küçük veya büyük bağ paket.',
		'body' => 'Tavlı Tel, ısıl işlemle yumuşatılmış düşük karbonlu teldir; elle bükülür, kırılmadan sarılır ve bağlandığı yerde gevşemez. Sertel bu teli krom potalarda ve elektrikli fırınlarda tavlar. Bu yöntemde yüzey parlak kalır, oksit tabakası (tufal) oluşmaz, kalınlık ve sertlik tel boyunca homojen dağılır. Çap aralığı 0,9–4,0 mm\'dir. Paketleme küçük bağ ya da büyük bağ olarak yapılır.

En bilinen kullanımı şantiyede inşaat demirinin bağlanmasıdır: etriye ile boyuna demirin kesiştiği noktalar ince tavlı telle sarılır. Kalın çaplar ise kereste demeti, palet istifi, hurda ve atık balyası bağlamada kullanılır. Ahşap kasa ve sandık üreticileri ağır parçaları sevkiyatta sabitlemek için de bu tele başvurur.

İnce çap el ile bağlamaya, kalın çap yük taşıyan bağlamaya uygundur. İşinizi anlatın, doğru çapı birlikte belirleyelim.

KOÇİST\'te tavlı tel için bağ ya da ton bazında ekonomik fiyatla hızlı teklif hazırlıyoruz. Stoktan teslim ediyor, İstanbul ve Trakya şantiyelerine kendi araçlarımızla ulaştırıyoruz. Çatalca showroomumuz açık. Tel: 0212 648 19 19.',
		'specs' => 'Malzeme: Düşük karbonlu tel
Tel çapı: 0,9–4,0 mm
