		'body' => 'Dışarıda kalacak bir bağlantı kuruyorsanız çıplak tel kısa sürede paslanır. Galvanizli Tel, yüzeyine elektrolitik yolla uygulanan çinko tabakası sayesinde bu sorunu geciktirir. Sertel\'in bu ürünü düşük karbonlu telden üretilir. Çap aralığı 0,9–5,0 mm\'dir, kaplama elektro galvanizdir ve paketleme büyük bağ şeklindedir.

Geniş çap aralığı tek bir ürünle çok farklı işlerin yapılmasını sağlar. İnce çaplar bağ ve bahçe telinde, fide ve sera askısında, ambalaj bağlamada kullanılır. Orta çaplar çit gerdirme, tel örgü onarımı ve kereste istifi bağlama için uygundur. Kalın çaplar ise taşıyıcı gergi teli, sundurma ve gölgelik bağlantısı gibi yük alan noktalarda işe yarar.

Palet ve kasa üreticileri açık stok sahasındaki kereste demetlerini bu telle bağlayarak yağmurda paslanma lekesi oluşmasını azaltır.

KOÇİST, galvanizli tel için ekonomik fiyatla hızlı teklif verir. Stokta olan çaplar hemen hazırlanır; İstanbul ve Trakya\'ya kendi araçlarımızla sevkiyat yapıyoruz. Çatalca showroomumuzda örnek bağları görebilirsiniz. WhatsApp: 0549 648 19 19.',
