	array(
		'slug' => 'galvanizli-dikis-teli',
		'title' => 'Galvanizli Dikiş Teli',
		'group' => 'tel-urunleri',
		'short' => 'Ambalaj sanayisinin bağlantı teli Galvanizli Dikiş Teli: 0,8–1,8 mm çap, elektro galvaniz, rozet veya küçük bağ.',
		'body' => 'Galvanizli Dikiş Teli, ambalaj sanayisinde bağlantı elemanı olarak kullanılan ince ve düzgün çaplı bir teldir. Sertel\'in ürünü düşük karbonlu telden üretilir ve elektro galvanizle kaplanır. Çap aralığı 0,8–1,8 mm\'dir. Paketleme rozet ya da küçük bağ şeklinde yapılır; rozet sarım makineye düzgün beslenir.

Bu tel, koli dikiş makinelerinde oluklu mukavva kutuların kenarlarını dikmek, kitap ve katalog sırtı dikmek, torba ağzı kapatmak ve hafif ambalaj bağlantıları kurmak için kullanılır. Galvaniz kaplama, depoda bekleyen ambalajlarda pas lekesi oluşmasını önler. Bu da gıda ve tekstil kolilerinde görünümü korur.

İnce çaplar hafif kartonda, 1,5 mm ve üzeri ağır kolide ve çok katlı ambalajda tercih edilir. Makinenizin kabul ettiği çapı ve sarım tipini iletirseniz doğru ürünü hazırlarız.

KOÇİST, ambalaj üreticilerine dikiş telinde ekonomik fiyat ve hızlı teklif sunar. Stoktan teslim ediyor, İstanbul ve Trakya\'daki tesislere kendi araçlarımızla taşıyoruz. Çatalca showroomumuza uğrayabilirsiniz. Tel: 0212 648 19 19.',
