		'short' => 'Geri dönüşüm balyaları için Balya Teli: 1,60–4,00 mm çap, SAE 1006/1008/1018 hammadde, çapraz veya düz sarım rulo.',
		'body' => 'Balya Teli, kâğıt, karton, plastik ve metal hurdanın preslenerek balya hâline getirildiği geri dönüşüm tesislerinin temel sarf malzemesidir. Sertel bu teli SAE 1006, SAE 1008 ve SAE 1018 kalite hammaddeden üretir. Ürün görselinde standart olarak TSE 2348 EN 1016 ibaresi yer alır. Çap aralığı 1,60–4,00 mm\'dir. Sarım çapraz ya da düz yapılır, paket rulo şeklindedir.

Telin yüzeyi kaydırıcı ve koruyucu yağla kaplanır. Kaydırıcı yağ, presin bağlama ünitesinde telin takılmadan ilerlemesini sağlar; koruyucu katman ise depoda bekleyen rulolarda paslanmayı geciktirir.

Karton balyaları için ince ve orta çaplar, metal ve yoğun plastik balyaları için kalın çaplar tercih edilir. Presinizin markasını ve tel besleme sistemini iletirseniz uygun çap ile sarım tipini birlikte seçeriz.

KOÇİST, düzenli tüketim yapan tesislere ekonomik fiyat ve hızlı teklif sunar. Stoktan teslim yapıyor, İstanbul ve Trakya\'ya kendi araçlarımızla sevkiyat sağlıyoruz. Çatalca showroomumuz da ziyarete açık. WhatsApp 0549 648 19 19.',
