		'body' => 'Stoper, hava hortumunu alet kullanmadan saniyeler içinde takıp çıkarmanızı sağlayan hızlı bağlantı parçasıdır. 3/8 İkili Stoper Set Pirinç ise bu kolaylığı ikiye katlar. Kompresörün ya da hava dağıtım hattının 3/8 inç çıkışına takılır ve iki ayrı stoper ağzı sunar.

