		'body' => 'Hava hattında her parça aynı diş ölçüsüne sahip olmaz. Kompresör çıkışı 1/2 inç iken regülatör ya da stoper 3/8 inç olabilir. 3/8″-1/2″ Nipel Pirinç, bu iki farklı diş ölçüsünü tek parçada birleştiren bir geçiş elemanıdır. Bir ucu 3/8, diğer ucu 1/2 inç dişlidir.

