		'body' => 'Hortumun ucunda stoper yoksa her tabanca değişiminde kelepçe sökmek gerekir. 5x8 Hortum Ucu Stoper Pirinç bu zahmeti ortadan kaldırır. Parça, 5x8 mm hava hortumunun ucuna takılır ve tabancanın erkek bağlantısına tek hareketle geçer.

