		'body' => 'TT130B 1/2″ Somun Sökme Tabancası Seti, 1/2 inç sınıfında daha yüksek tork arayanlar için hazırlanmış çantalı bir pakettir. Sertel teknik tablosuna göre içerik şöyledir: 1 adet M-12F01B6 somun sökme tabancası, 10 adet lokma, 1 alyan anahtar, 1 nipel, 1 rekor ve 1 plastik çanta.

