		'body' => 'Şantiyede kompresör ve hortum taşımak her zaman mümkün değildir. AKD T30/38 N1 Çivi Çakma Tabancası bu sorunu gaz tüpüyle çözer: çakım enerjisini 165 mm\'lik gaz kartuşundan, ateşleme gücünü ise 1,65 Ah Ni-MH bataryadan alır. Sertel teknik tablosunda ağırlık 3,92 kg, ölçüler 459x116x375 mm, magazin kapasitesi 22 çivi ve çivi boyu 15–40 mm olarak verilir. Tabanca plastiğe dizili çivi kullanır.

