		'body' => 'Zor şantiye koşullarında, elektriğin ve hava hattının olmadığı yerlerde güvenilir bir sabitleme aracı gerekir. AKD 450 Barutlu Çivi Çakma Tabancası tam bu ihtiyaç için vardır. Sertel teknik tablosunda ölçüler 350 mm uzunluk, 56 mm genişlik ve 180 mm yükseklik, ağırlık 3,2 kg, kartuş kapsül ise 6,8–11 mm olarak verilir.

Görselde üç bağlantı türü sıralanır: ahşabı betona, çeliği betona ve çeliği çeliğe birleştirmek. Bu esneklik, aynı tabancayla kalıp latası çakmaktan çelik konstrüksiyona bağlantı plakası sabitlemeye kadar farklı işlerin yapılmasını sağlar.

Kompakt gövdesi (56 mm genişlik), duvar köşelerine ve profil aralarına girmeyi kolaylaştırır. Kereste ve palet sahalarında beton zemine ahşap ray, çelik raf ayağı ve bariyer bağlantısı yapmak için de kullanılır.

Barutlu tabancalar kapsül ve çiviyle birlikte planlanır; KOÇİST bu üçlüyü tek teklifte, ekonomik fiyatla sunar. Hızlı dönüş yapıyor, stoktan teslim ediyor, İstanbul–Trakya\'ya kendi araçlarımızla taşıyoruz. Çatalca\'daki showroomumuzda aleti test etmeniz mümkün. WhatsApp: 0549 648 19 19.',
