		'body' => 'Mantolama Dübelleri, dış cephe ısı yalıtımında EPS ya da taşyünü levhayı duvara mekanik olarak bağlayan, geniş başlı plastik bağlantı elemanlarıdır. Sertel listesinde ID30\'dan ID90\'a kadar yedi kod bulunur. Çivi boyu ID30\'da 37 mm, ID40–ID60\'ta 52 mm, ID70–ID90\'da 55 mm\'dir. Kutu içeriği ID30–ID60 arasında 1.000 dübel, ID70–ID90 arasında 500 dübeldir.

Koddaki sayı, dübelin uygun olduğu yalıtım kalınlığı sınıfını gösterir. İnce levhalarda küçük kodlar, kalın levhalarda büyük kodlar seçilir. Doğru boy, dübel başının levha yüzeyine tam oturmasını ve sıva filesinin düzgün kalmasını sağlar.

Bu dübeller, KOÇİST\'teki NAIL GSN 40 D Mantolama Dübeli Çakma Tabancası ile tek atışta çakılır. Bu yöntem, her nokta için ayrı matkap deliği açma ihtiyacını ortadan kaldırarak cephe işçiliğini önemli ölçüde hızlandırır.

Cephe ve yalıtım firmalarına koli bazında ekonomik fiyat ve hızlı teklif sunuyoruz. Stoktan teslim yapıyor, İstanbul ve Trakya şantiyelerine kendi araçlarımızla taşıyoruz. Çatalca showroomumuzda dübel boylarını karşılaştırabilirsiniz. WhatsApp 0549 648 19 19.',
