		'body' => 'Tek tek vida takıp sıkmak yerine, vidaları bir şerit üzerinde dizili olarak besleyen tabancalar montaj hızını katlar. AKD EA08 Şerit Tipi Elektrikli Vidalama Tabancası bu sistemle çalışır. Sertel teknik tablosuna göre magazin kapasitesi 50 adettir; uzunluk 500 mm\'dir.

Şerit sistemde operatör vidayı eline almaz. Tabanca yüzeye bastırıldığında sıradaki vida ucun önüne gelir ve sıkılır. Böylece bir eliyle levhayı tutan usta diğer eliyle seri vidalama yapabilir. Alçı levha duvar ve tavan montajı, OSB ve kontrplak kaplama, mobilya arkalık ve çekmece tabanı tipik kullanımlardır.

Sertel görselindeki nota göre şerit tipi vidalar Mersin Tarsus OSB\'deki tesislerde üretilir. KOÇİST bu vidaları da tabancayla birlikte tedarik edebilir.

