		'body' => 'Kablosuz çalışmak, şantiyede uzatma kablosu çekme derdini ortadan kaldırır. AKD BL 18SG Şerit Tipi Şarjlı Vidalama Tabancası, şerit vida sistemini akülü bir gövdeyle birleştirir. Sertel teknik tablosuna göre magazin kapasitesi 50 adettir ve ürün özellikle mobilya ile alçı levha sektörüne yönelik olarak tanımlanır.

