Mutfak ve gardırop montajı, alçı levha bölme duvar, tavan kaplaması ve ahşap lambri bu tabancanın öne çıktığı işlerdir. Aynı vidayı yüzlerce kez tekrar eden montaj ekipleri için iş süresini belirgin şekilde kısaltır.

