		'group' => 'mobilya-tabancalari',
		'short' => 'Koltukta dekoratif kabara için NAIL TD25 Set Kabara Çivi Tabancası; süs çivilerini hizalı ve eşit derinlikte çakar.',
		'body' => 'Chesterfield koltuk, berjer ve klasik sandalyelerde kumaş kenarını takip eden pirinç ya da nikel süs çivileri, yani kabaralar, ürünün karakterini belirler. Bu çivileri çekiçle tek tek çakmak hem yavaştır hem de hizayı bozar. NAIL TD25 Set Kabara Çivi Tabancası bu işi havalı tabanca hızına taşır.

Tabanca, kabarayı başını ezmeden ve her seferinde aynı derinlikte çakacak şekilde tasarlanmıştır. Böylece uzun bir kenar boyunca dizilen kabaralar aynı yükseklikte ve düzgün bir sıra hâlinde durur. Ürün Sertel\'in sayfasında "set" olarak listelenir. Sertel teknik tablosuna göre gövde 0,625 kg\'dır ve 10–17 mm uzunluktaki kabaralarla çalışır.

Kullanım alanları: klasik koltuk ve kanepe kenarları, yatak başlığı, deri sandalye, sandık ve bavul süslemesi, kapı kaplaması ve dekoratif panel. Ahşap sandık üreticileri hediye ve vintage tasarım kutularda da kabara kullanır.

KOÇİST\'te döşeme atölyelerine bu seti ekonomik fiyat ve hızlı teklifle sunuyoruz. Stoktaki ürünler İstanbul ve Trakya genelinde kendi araçlarımızla dağıtılır. Çatalca showroomumuzda kabara uygulamasını deneyebilirsiniz. WhatsApp: 0549 648 19 19.',
