		'body' => 'AKDT NCF Zıvana Çivi Tabancası, AKDT serisinin zıvana çivisi kullanan modelidir ve aynı kategorideki T CF155\'e alternatif bir gövde sunar. İki model arasındaki tercih çoğu zaman atölyedeki diğer AKDT aletleriyle uyum ve elde tutuş hissine göre yapılır.

