		'body' => 'Tablo, ayna ve fotoğraf çerçevesi üretiminde köşeler 45 derece gönye ile kesilir ve bu birleşimin önden görünmeden sağlam tutması gerekir. AKD V15EH V Çivi Tabancası bu işi V biçimli özel çiviyle yapar. Çivi, gönye çizgisinin iki tarafına arka yüzden girer ve iki parçayı birbirine kilitler.

