		'body' => 'C-ring, açık bir halka biçimindeki klipstir; tabancanın ağzında kapanarak iki teli ya da teli bir kumaşa bağlar. AKD TC7/AC04 C-Ring Tabancası bu kapama işlemini havalı güçle, her seferinde aynı sıkılıkta yapar.

En yaygın kullanım alanı yaylı yatak ve koltuk yay sistemleridir. Yay ünitesini çerçeve teline bağlamak, yay sırasını birbirine tutturmak ve yatak kılıfının iç katmanını tel iskelete sabitlemek bu tabancanın günlük işleridir. Yatak sektörünün dışında tel kafes, hayvan bölmesi, çit teli, file ve gabion sepeti montajında da kullanılır.

