		'body' => 'Saha montajında hem kablo hem hortum derdinden kurtulmak isteyenler için AKD DBAF50/40 Şarjlı Zımba / Brad Tabancası iki özelliği birleştirir: akülü çalışır ve tek gövdede hem zımba teli hem brad çivi atar.

Sertel teknik tablosuna göre 18 V DC ile çalışır; normalde dakikada 30, en fazla 60 atış yapar. Çivi tarafında 40 mm\'ye kadar 18 GA brad, zımba tarafında 90 serisi tel kullanır; magazin 100 adet alır.

Kullanım senaryosu: müşteri sahasında mobilya kurulumu, mağaza dekoru, fuar standı, çatı katında lambiri ya da bahçede ahşap çit tamiri. Elektriğin ve kompresörün olmadığı her yerde zımba ile brad arasında alet değiştirmeden çalışılır.

KOÇİST\'teki 90 Serisi 18 GA Zımba Teli ve 18 GA Brad Çivi bu tabancanın sarf malzemesidir; uygun boyları birlikte seçeriz. Ekonomik fiyat ve hızlı teklif sunuyoruz. İstanbul–Trakya teslimatını kendi araçlarımızla yapıyor, stoktan hızlı çıkış sağlıyoruz; Çatalca showroomumuzda ürünü inceleyebilirsiniz. Tel: 0212 648 19 19.',
		'specs' => 'Şarj cihazı girişi: 100–240 V, 50/60 Hz
Voltaj: 18 V DC
Atış hızı: normal 30, maks. 60 çivi/dk
Magazin kapasitesi: 100 adet
Çivi: 18 GA brad, 40 mm\'ye kadar
Zımba teli: 90 serisi',
