		'title' => 'AKD 18/32 Elektrikli Brad Tabancası',
		'group' => 'mobilya-tabancalari',
		'short' => 'Hafif işler için AKD 18/32 Elektrikli Brad Tabancası; 18 GA brad çiviyi kompresörsüz çakar, ev ve atölye montajında pratik.',
		'body' => 'Her brad işi profesyonel bir kompresör kurulumu gerektirmez. AKD 18/32 Elektrikli Brad Tabancası, prize takılarak çalışan ve 18 GA brad çiviyle hafif montaj işlerini hızlandıran bir modeldir. Sertel teknik tablosuna göre 1,25x1,05 mm kesitli, 10–35 mm boyunda elektro galvaniz brad çivi kullanır; magazin 100 adet alır, gövde 1,05 kg\'dır.

10–35 mm aralığı, mobilya ve dekorasyonun ince işlerine odaklanır. Dolap arkalığı, çekmece tabanı, ince çıta ve profil, tablo ve ayna çerçevesi, hobi ve maket işleri, küçük ahşap kutu ve hediye ambalajı bu tabancanın uygun olduğu işlerdir.

Elektrikli tabancalar showroom, mağaza ve ofis gibi kompresör gürültüsünün istenmediği ortamlarda da rahatça kullanılır. Kısa süreli tamir işleri için atölyede yedek tabanca olarak tutmak da mantıklıdır.

KOÇİST\'teki 18 GA Brad Çivi\'den bu tabancaya uyan boyları birlikte seçeriz. 0212 648 19 19 hattından teklif isteyin; miktara göre en uygun fiyatı çıkaralım. Stoktan teslim ediyoruz; İstanbul ve Trakya\'daki şantiye ve atölyelere kendi aracımızla geliyoruz. Çatalca showroomumuzda elektrikli ve havalı modelleri karşılaştırabilirsiniz.',
