	array(
		'slug' => 'ro-ma-maestri-me80-doseme-tabancasi',
		'title' => 'RO-MA Maestri ME80 Zımba Döşeme Tabancası',
		'group' => 'mobilya-tabancalari',
		'short' => 'Profesyonel döşemeciler için RO-MA Maestri ME80 Zımba Döşeme Tabancası; İtalyan RO-MA markasının döşeme zımbası.',
		'body' => 'RO-MA, döşeme tabancalarında uzmanlaşmış bir markadır ve Maestri serisi markanın profesyonel kullanıcıya yönelik ürün grubudur. RO-MA Maestri ME80 Zımba Döşeme Tabancası bu serinin döşeme odaklı modelidir. Sertel ürün sayfasında RO-MA logosuyla birlikte listelenir.

Sertel teknik tablosuna göre 80 serisi, 12,7 mm taçlı ve 4–16 mm boyunda zımba teli kullanır; magazin 110 adet alır, gövde 1,4 kg\'dır ve plastik çantasıyla gelir.

Profesyonel döşeme tabancası seçerken üç şeye bakılır: tetik hassasiyeti, gövde dengesi ve burun ucunun görüş açısı. Maestri serisi bu üç noktada usta döşemecilerin beklentisine göre tasarlanır. Koltuk ve kanepe, sandalye ve berjer, yatak başlığı, araç ve tekne döşemesi gibi kalite beklentisi yüksek işlerde tercih edilir.

Atölyenizde gün boyu çalışacak ana tabancayı seçiyorsanız Çatalca showroomumuzda ME80\'i diğer döşeme tabancalarıyla karşılaştırabilirsiniz.

KOÇİST\'teki 80 Serisi Zımba Teli bu tabancanın sarf malzemesidir. Tabanca ve teli ekonomik fiyatla, aynı gün teklifle sunuyoruz. Ürün depomuzdan hızla çıkar, İstanbul ve Trakya\'ya kendi taşıtlarımızla teslim edilir. WhatsApp: 0549 648 19 19.',
		'specs' => 'Tür: 80 serisi
