	array(
		'slug' => 'ro-ma-maestri-me30-doseme-tabancasi',
		'title' => 'RO-MA Maestri ME30 Zımba Döşeme Tabancası',
		'group' => 'mobilya-tabancalari',
		'short' => 'RO-MA Maestri ME30 Zımba Döşeme Tabancası; 80 serisi telde 15–30 mm boy, 110 adet magazin, 1,4 kg gövde.',
		'body' => 'RO-MA Maestri ME30 Zımba Döşeme Tabancası, RO-MA\'nın profesyonel Maestri serisinden ikinci döşeme modelidir. Sertel ürün sayfasında markanın logosu ve ürünün açıklama görseliyle birlikte listelenir. Sertel teknik tablosuna göre 80 serisi, 15–30 mm boyunda zımba teli kullanır; magazin 110 adet alır, gövde 1,4 kg\'dır ve plastik çantasıyla gelir. ME80 4–16 mm kısa tellerle, ME30 ise 15–30 mm uzun tellerle çalışır.

Profesyonel döşeme atölyelerinde tek tabanca ile çalışılmaz. Ana döşeme için bir model, detay ve ince işler için ikinci bir model bulundurmak yaygındır. ME30 uzun tel, ME80 kısa tel tarafını karşıladığı için iki model bu ikili düzende birbirini tamamlar.

Kullanım alanları: koltuk ve sandalye döşemesi, berjer kenarları, yatak başlığı paneli, dekoratif duvar paneli kaplama, araç içi döşeme ve kutu kaplama işleri.

Çatalca showroomumuzda ME30\'u elinize alıp kumaş üzerinde deneme atışı yapabilirsiniz.

KOÇİST, RO-MA tabancalarını döşeme telleriyle birlikte ekonomik fiyat ve hızlı teklifle sunar. İstanbul–Trakya teslimatlarını stoktan, kendi araçlarımızla ve gecikmeden yapıyoruz. Tel: 0212 648 19 19.',
